import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { isAuthenticated, logout, isAdmin } from '../utils/auth';

export default function Navbar(){
  const navigate = useNavigate();
  const auth = isAuthenticated();
  const admin = isAdmin();
  const name = localStorage.getItem('name');

  function doLogout(){ logout(); navigate('/'); }

  return (
    <nav className="bg-white shadow-sm">
      <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
        <Link to="/" className="text-2xl font-bold text-blue-600">BookStore</Link>
        <div className="flex items-center gap-4">
          <Link to="/" className="text-gray-700 hover:text-blue-600">Home</Link>
          <Link to="/cart" className="text-gray-700 hover:text-blue-600">Cart</Link>
          {admin && <Link to="/admin" className="text-gray-700 hover:text-blue-600">Admin</Link>}
          {auth ? (
            <>
              <span className="text-gray-600">Hi, {name || 'User'}</span>
              <button onClick={doLogout} className="bg-red-500 text-white px-3 py-1 rounded">Logout</button>
            </>
          ) : (
            <>
              <Link to="/login" className="text-gray-700 hover:text-blue-600">Login</Link>
              <Link to="/register" className="text-gray-700 hover:text-blue-600">Register</Link>
            </>
          )}
        </div>
      </div>
    </nav>
  );
}
